const cookieHeader = $json.headers['set-cookie'];
const sessionCookie = cookieHeader.find(c => c.includes("session_id="));
const sessionId = sessionCookie.match(/session_id=([^;]+)/)[1];

return [{
  json: {
    cookie: `session_id=${sessionId}`
  }
}];

