const items = $input.all();

for (const item of items) {
  const response = item.json;

  if (response.error) {
    const message = response.error.message || JSON.stringify(response.error);
    throw new Error(`Odoo no pudo publicar el producto: ${message}`);
  }

  if (response.result !== true) {
    throw new Error(`Odoo no confirmó la publicación: ${JSON.stringify(response)}`);
  }
}

return items;

const items = $input.all();

for (const item of items) {
  const response = item.json;

  if (response.error) {
    const message = response.error.message || JSON.stringify(response.error);
    throw new Error(`Odoo no pudo despublicar el producto: ${message}`);
  }

  if (response.result !== true) {
    throw new Error(`Odoo no confirmó la despublicación: ${JSON.stringify(response)}`);
  }
}

return items;

